using State = std::variant<AwaitingPayment, AwaitingStock, Compensating, Done>;

State step(const State& s, const Reply& r, Store& db) {
  return std::visit(overloaded{
    [&](const AwaitingPayment&) -> State {
      if (!r.ok) return Compensating{r.cid, r.error};
      db.save(AwaitingStock{r.cid});            // same tx as the command
      return AwaitingStock{r.cid};
    },
    [&](const AwaitingStock&) -> State { return Done{}; },
    [&](const auto&) -> State { return s; },     // stale reply
  }, s);
}

