struct OrderFsm : msm::front::state_machine_def<OrderFsm> {
  struct AwaitingPayment : msm::front::state<> {
    template <class Ev, class Fsm, class Any>
    void on_entry(Ev const&, Fsm& f, Any&) { f.arm_deadline(); }
  };
  typedef AwaitingPayment initial_state;
  struct transition_table : boost::mpl::vector<
    //  Start            Event        Next           Action
    Row<AwaitingPayment, PaymentOk,   AwaitingStock, ReserveStock>,
    Row<AwaitingPayment, Timeout,     Compensating,  ReleaseCredit>,
    Row<AwaitingStock,   ReserveOk,   Done,          Ship> > {};
};
